edges = [(0,4), (0,5), (0,9), (1,2), (1,3), (1,5), (1,10), (2,3), (2,8), (2,9), (3,7), (3,8), (4,6), (4,7), (5,7), (5,10), (6,9), (6,10), (8,9)]

n = 11
adj = [[] for _ in range(n)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Check bipartiteness
color = [-1]*n
def is_bipartite():
    for start in range(n):
        if color[start] == -1:
            stack = [(start, 0)]
            color[start] = 0
            while stack:
                v, c = stack.pop()
                for u in adj[v]:
                    if color[u] == -1:
                        color[u] = 1-c
                        stack.append((u, 1-c))
                    elif color[u] == c:
                        return False
    return True

print("Is bipartite?", is_bipartite())

# Check 4-colorability
def chromatic_leq(k):
    colors = [-1]*n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

print("4-colorable?", chromatic_leq(4))
print("3-colorable?", chromatic_leq(3))
print("2-colorable?", chromatic_leq(2))

# Check degrees
